import Foundation
import NIO
import NIOWebSocket

final class ChatServer {
    private let group: MultiThreadedEventLoopGroup
    private var channel: Channel?
    private var sessions: [String: ChatSession] = [:]
    private let sessionLock = NSLock()
    private var isShuttingDown = false

    struct ChatSession {
        let username: String
        let normalizedUsername: String
        let channel: Channel
        var messageCount: Int
        var isAdmin: Bool
    }

    init(threads: Int = System.coreCount) {
        self.group = MultiThreadedEventLoopGroup(numberOfThreads: threads)
    }

    func normalizeUsername(_ raw: String) -> String {
        // NFC normalization for consistent storage
        let nfc = raw.precomposedStringWithCanonicalMapping
        // Strip zero-width characters for display safety
        let stripped = nfc.unicodeScalars.filter { scalar in
            scalar.value != 0x200B && // zero-width space
            scalar.value != 0x200C && // zero-width non-joiner
            scalar.value != 0x200D && // zero-width joiner
            scalar.value != 0xFEFF    // BOM
        }
        return String(String.UnicodeScalarView(stripped))
    }

    func validateUsername(_ username: String) -> Bool {
        guard username.count >= 3 && username.count <= 20 else { return false }
        let allowed = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "_-"))
        return username.unicodeScalars.allSatisfy { allowed.contains($0) }
    }

    func registerSession(rawUsername: String, channel: Channel) -> Result<ChatSession, ChatError> {
        // Step 1: Normalize FIRST before any checks
        let normalized = normalizeUsername(rawUsername)

        // Step 2: Validate the normalized form
        guard validateUsername(normalized) else {
            return .failure(.invalidUsername)
        }

        // Step 3: Check uniqueness against normalized username
        sessionLock.lock()
        let existing = sessions[normalized]
        sessionLock.unlock()

        if existing != nil {
            return .failure(.usernameTaken)
        }

        // Step 4: Reject reserved admin names for new registrations
        let reservedNames = ["admin", "moderator", "system"]
        if reservedNames.contains(normalized.lowercased()) {
            return .failure(.invalidUsername)
        }

        let session = ChatSession(
            username: normalized,
            normalizedUsername: normalized,
            channel: channel,
            messageCount: 0,
            isAdmin: false
        )

        // Step 5: Store using normalized key
        sessionLock.lock()
        sessions[normalized] = session
        sessionLock.unlock()

        return .success(session)
    }

    func handleMessage(_ message: String, from session: ChatSession) -> MessageResult {
        guard !isShuttingDown else {
            return .rejected(reason: "Server shutting down")
        }

        if message.hasPrefix("/kick ") && session.isAdmin {
            let target = String(message.dropFirst(6))
            return kickUser(target)
        }

        if message.hasPrefix("/broadcast ") && session.isAdmin {
            let content = String(message.dropFirst(11))
            return broadcastSystem(content)
        }

        return deliverMessage(message, from: session)
    }

    func kickUser(_ target: String) -> MessageResult {
        sessionLock.lock()
        let targetNormalized = normalizeUsername(target)
        if let targetSession = sessions[targetNormalized] {
            sessions.removeValue(forKey: targetNormalized)
            sessionLock.unlock()
            targetSession.channel.close(promise: nil)
            return .success
        }
        sessionLock.unlock()
        return .rejected(reason: "User not found")
    }

    func broadcastSystem(_ content: String) -> MessageResult {
        sessionLock.lock()
        let allSessions = Array(sessions.values)
        sessionLock.unlock()

        for s in allSessions {
            let frame = WebSocketFrame(fin: true, opcode: .text, data: ByteBuffer(string: "[SYSTEM] \(content)"))
            s.channel.writeAndFlush(frame, promise: nil)
        }
        return .success
    }

    func deliverMessage(_ message: String, from session: ChatSession) -> MessageResult {
        sessionLock.lock()
        let allSessions = Array(sessions.values)
        sessionLock.unlock()

        let payload = "[\(session.username)] \(message)"
        for s in allSessions where s.normalizedUsername != session.normalizedUsername {
            let frame = WebSocketFrame(fin: true, opcode: .text, data: ByteBuffer(string: payload))
            s.channel.writeAndFlush(frame, promise: nil)
        }
        return .success
    }

    func gracefulShutdown() {
        isShuttingDown = true
        sessionLock.lock()
        let allSessions = Array(sessions.values)
        sessions.removeAll()
        sessionLock.unlock()

        for s in allSessions {
            let frame = WebSocketFrame(fin: true, opcode: .text, data: ByteBuffer(string: "[SYSTEM] Server shutting down"))
            s.channel.writeAndFlush(frame, promise: nil)
            s.channel.close(promise: nil)
        }

        try? group.syncShutdownGracefully()
    }
}

enum ChatError: Error {
    case invalidUsername
    case usernameTaken
    case serverShuttingDown
}

enum MessageResult {
    case success
    case rejected(reason: String)
}
